@push('scripts')<script>$(function(){const esc=s=>$('<div>').text(s??'-').html(),badge=s=>({DRAFT:'app-badge-soft',CONFIRMED:'app-badge-success',FULFILLED:'app-badge-success',CANCELLED:'text-bg-danger'}[s]||'app-badge-soft'),date=s=>{if(!s)return'-';const m=String(s).match(/^(\d{4})-(\d{2})-(\d{2})/);return m?`${m[3]}/${m[2]}/${m[1]}`:esc(s)},saleState=s=>({CREATED:['app-badge-success','สร้างแล้ว'],VOIDED:['text-bg-danger','ยกเลิกแล้ว'],NONE:['app-badge-soft','ยังไม่สร้าง']}[s]||['app-badge-soft','—']);const table=$('#order-table');const t=table.DataTable({...window.erpDataTableDefaults,buttons:[window.erpExcelButton(table)],ajax:{url:table.data('url'),data:d=>{d.date_from=$('#order-from').val();d.date_to=$('#order-to').val();d.status=$('#order-status').val()}},columns:[{data:'document_number',render:(d,_,r)=>`<a href="${r.show_url}">${esc(d)}</a>`},{data:'document_date',render:date},{data:'party_label',render:esc},{data:'source_label',render:esc},{data:'lines_count'},{data:'total_amount',render:d=>Number(d||0).toLocaleString(undefined,{minimumFractionDigits:2})},{data:'status_label',render:(d,_,r)=>`<span class="badge ${badge(r.status)}">${esc(d)}</span>`},{data:'physical_sale_label',render:(d,_,r)=>{const [c,l]=saleState(r.physical_sale_status);return r.physical_sale_url?`<a href="${r.physical_sale_url}" class="text-decoration-none"><span class="badge ${c}">${esc(d)}</span></a>`:`<span class="badge ${c}">${l}</span>`;}},{data:null,orderable:false,render:(_,__,r)=>`<a class="btn btn-sm btn-app-soft" title="ดูรายละเอียด" aria-label="ดูรายละเอียด" href="${r.show_url}"><i class="bx bx-show"></i></a> <a class="btn btn-sm btn-app-soft" title="พิมพ์ PDF" aria-label="พิมพ์ PDF" href="${r.pdf_url}"><i class="bx bx-printer"></i></a>${r.physical_sale_create_url?` <a class="btn btn-sm btn-primary" title="สร้าง HS/IV" aria-label="สร้าง HS/IV" href="${r.physical_sale_create_url}"><i class="bx bx-receipt"></i></a>`:''}`}]});$('#order-filter').on('click',()=>t.ajax.reload());});</script>@endpush
